#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    vector<int> digits(1, 1);
    for (int k = 2; k <= n; k++) {
        int carry = 0;
        for (int i = 0; i < (int) digits.size(); i++) {
            int value = digits[i] * k + carry;
            digits[i] = value % 10;
            carry = value / 10;
        }
        while (carry > 0) {
            digits.push_back(carry % 10);
            carry /= 10;
        }
    }
    for (int i = (int) digits.size() - 1; i >= 0; i--) {
        cout << digits[i];
    }
    cout << endl;

    return 0;
}

